import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;

public class ConfigReader {
    public void loadConfig(Path configFile) throws IOException {
        // Modern way: specify encoding explicitly
        try (var reader = new FileReader(configFile.toFile(), StandardCharsets.UTF_8);
             var buffered = new BufferedReader(reader)) {

            String line;
            while ((line = buffered.readLine()) != null) {
                if (line.startsWith("#") || line.isBlank()) continue;

                var parts = line.split("=", 2);
                String key = parts[0].trim();
                String value = parts.length > 1 ? parts[1].trim() : "";
                System.out.println("Config: " + key + " = " + value);
            }
        }
    }
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.stream.Stream;

public class LogReader {
    // Traditional approach with full control
    public void readWithLoop(Path logFile) throws IOException {
        try (var reader = Files.newBufferedReader(logFile, StandardCharsets.UTF_8)) {
            String line;
            int lineNumber = 0;
            while ((line = reader.readLine()) != null) {  // null = end of file
                lineNumber++;
                if (line.contains("ERROR")) {
                    System.out.println("Line " + lineNumber + ": " + line);
                }
            }
        }
    }

    // Modern stream approach
    public void readWithStream(Path logFile) throws IOException {
        try (Stream<String> lines = Files.lines(logFile, StandardCharsets.UTF_8)) {
            lines.filter(line -> line.contains("ERROR"))
                 .forEach(System.out::println);  // lazy - processes one line at a time
        }
    }
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.LocalDateTime;
import java.util.List;

public class LogWriter {
    private final Path logFile = Path.of("app.log");

    // Simple one-liner for single message
    public void logSimple(String message) throws IOException {
        var entry = LocalDateTime.now() + " " + message + "\n";
        Files.writeString(logFile, entry, StandardCharsets.UTF_8,
            StandardOpenOption.CREATE, StandardOpenOption.APPEND);
    }

    // Write multiple lines at once
    public void logBatch(List<String> messages) throws IOException {
        Files.write(logFile, messages, StandardCharsets.UTF_8,
            StandardOpenOption.CREATE, StandardOpenOption.APPEND);
    }

    // BufferedWriter for incremental logging
    public void logStream(Stream<String> events) throws IOException {
        try (var writer = Files.newBufferedWriter(logFile, 
                StandardCharsets.UTF_8, StandardOpenOption.CREATE, StandardOpenOption.APPEND)) {
            events.forEach(event -> {
                try {
                    writer.write(LocalDateTime.now() + " " + event);
                    writer.newLine();  // platform-independent line separator
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            });
        }
    }
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.LocalDate;
import java.util.List;

record SalesRecord(String product, int quantity, double price) {}

public class ReportGenerator {
    public void generateSalesReport(Path outputFile, List<SalesRecord> sales) {
        try (var writer = new PrintWriter(
                Files.newBufferedWriter(outputFile, StandardCharsets.UTF_8))) {

            writer.println("Sales Report - " + LocalDate.now());
            writer.println("=" .repeat(60));
            writer.println();

            // printf-style formatting
            writer.printf("%-20s %10s %12s %12s%n", 
                "Product", "Quantity", "Unit Price", "Total");
            writer.println("-".repeat(60));

            double grandTotal = 0;
            for (var sale : sales) {
                double total = sale.quantity() * sale.price();
                writer.printf("%-20s %10d $%11.2f $%11.2f%n",
                    sale.product(), sale.quantity(), sale.price(), total);
                grandTotal += total;
            }

            writer.println("-".repeat(60));
            writer.printf("Grand Total: $%.2f%n", grandTotal);

            if (writer.checkError()) {  // check for suppressed errors
                System.err.println("Error occurred while writing report");
            }
        } catch (IOException e) {
            System.err.println("Failed to create report: " + e.getMessage());
        }
    }
}

import java.io.*;
import java.util.List;

record OrderItem(String name, int quantity, double price) {}

public class InvoiceGenerator {
    public void generateInvoice(Writer output, List<OrderItem> items) throws IOException {
        var printer = new PrintWriter(output);
        printer.println("INVOICE");
        printer.println("=" .repeat(40));

        double total = 0;
        for (var item : items) {
            double lineTotal = item.quantity() * item.price();
            printer.printf("%s x%d @ $%.2f = $%.2f%n", 
                item.name(), item.quantity(), item.price(), lineTotal);
            total += lineTotal;
        }

        printer.printf("\nTotal: $%.2f%n", total);
        printer.flush();
    }
}

class InvoiceGeneratorTest {
    void testInvoiceGeneration() throws IOException {
        var generator = new InvoiceGenerator();
        var output = new StringWriter();  // capture output in memory

        var items = List.of(
            new OrderItem("Widget", 2, 10.50),
            new OrderItem("Gadget", 1, 25.00)
        );

        generator.generateInvoice(output, items);

        String invoice = output.toString();  // retrieve generated content
        assert invoice.contains("INVOICE");
        assert invoice.contains("Widget x2");
        assert invoice.contains("Total: $46.00");
    }
}
